import { writeFileSync } from 'node:fs'
import html from '../src/vocabularies/html.js'
import mathml from '../src/vocabularies/mathml.js'
import svg from '../src/vocabularies/svg.js'

const aliases = { var: 'htmlvar', switch: 'svgswitch',
                  'annotation-xml': 'annotationXml' }

const generate = (name, descriptions, docs, namespace) => {
  const lines = [
    '// Generated by scripts/generate-vocabularies.js.',
    `// Source: src/vocabularies/${name}.js`,
    "import { element } from './core/element.js'"
  ]
  if (namespace)
    lines.push(`import { ${namespace} } from './core/namespaces.js'`)

  for (const [tag, description] of Object.entries(descriptions)) {
    const args = namespace ? `'${tag}', ${namespace}` : `'${tag}'`
    lines.push('', '/**', ...description.split('\n').map(line => ` * ${line}`),
               ` * https://developer.mozilla.org/en-US/docs/Web/${docs}/${tag}`,
               ' */', `export const ${aliases[tag] ?? tag} = element(${args})`)
  }
  writeFileSync(new URL(`../src/${name}.js`, import.meta.url),
                lines.join('\n') + '\n')
}

generate('html', html, 'HTML/Reference/Elements')
generate('svg', svg, 'SVG/Reference/Element', 'svgNS')
generate('mathml', mathml, 'MathML/Element', 'mathNS')
